import json

_todos = []
_next_id = 1


def _new_id():
    global _next_id
    value = str(_next_id)
    _next_id += 1
    return value


def _find(todo_id):
    for t in _todos:
        if t["id"] == todo_id:
            return t
    return None


def _parse_body(body):
    if not body:
        return None, (400, {"error": "請求內容必須是 JSON 物件"})
    try:
        data = json.loads(body.decode("utf-8"))
    except Exception:
        return None, (400, {"error": "請求內容不是有效的 JSON"})
    if not isinstance(data, dict):
        return None, (400, {"error": "請求內容必須是 JSON 物件"})
    return data, None


def _public(t):
    return {"id": t["id"], "title": t["title"], "done": t["done"]}


def _list_todos():
    return 200, {"items": [_public(t) for t in _todos]}


def _create_todo(body):
    data, err = _parse_body(body)
    if err:
        return err
    title = data.get("title")
    if not isinstance(title, str):
        return 400, {"error": "標題必須是文字"}
    title = title.strip()
    if not title:
        return 400, {"error": "標題不可為空"}
    todo = {"id": _new_id(), "title": title, "done": False}
    _todos.append(todo)
    return 201, _public(todo)


def _update_todo(todo_id, body):
    todo = _find(todo_id)
    if todo is None:
        return 404, {"error": "找不到指定的待辦事項"}
    data, err = _parse_body(body)
    if err:
        return err
    if "done" not in data or not isinstance(data["done"], bool):
        return 400, {"error": "done 必須是布林值"}
    todo["done"] = data["done"]
    return 200, _public(todo)


def _delete_todo(todo_id):
    todo = _find(todo_id)
    if todo is None:
        return 404, {"error": "找不到指定的待辦事項"}
    _todos.remove(todo)
    return 200, {"deleted": True, "id": todo_id}


def _stats():
    total = len(_todos)
    remaining = sum(1 for t in _todos if not t["done"])
    return 200, {"remaining": remaining, "total": total}


def handle(method, path, body):
    method = (method or "").upper()
    path = path or "/"
    if not path.startswith("/"):
        path = "/" + path
    if len(path) > 1 and path.endswith("/"):
        path = path.rstrip("/") or "/"

    if path == "/todos":
        if method == "GET":
            return _list_todos()
        if method == "POST":
            return _create_todo(body)
        return 405, {"error": "不支援的請求方法"}

    if path.startswith("/todos/"):
        todo_id = path[len("/todos/"):]
        if not todo_id or "/" in todo_id:
            return 404, {"error": "找不到此路徑"}
        if method == "PATCH":
            return _update_todo(todo_id, body)
        if method == "DELETE":
            return _delete_todo(todo_id)
        return 405, {"error": "不支援的請求方法"}

    if path == "/stats":
        if method == "GET":
            return _stats()
        return 405, {"error": "不支援的請求方法"}

    return 404, {"error": "找不到此路徑"}

