(function () {
  'use strict';

  var form = document.getElementById('add-form');
  var input = document.getElementById('title-input');
  var addButton = document.getElementById('add-button');
  var messageEl = document.getElementById('message');
  var counterEl = document.getElementById('counter');
  var listEl = document.getElementById('todo-list');
  var emptyEl = document.getElementById('empty');

  // ---- api-client ----
  function apiRequest(method, path, body) {
    var options = { method: method, headers: {} };
    if (body !== undefined) {
      options.headers['Content-Type'] = 'application/json';
      options.body = JSON.stringify(body);
    }
    return fetch('api/' + path, options).then(function (res) {
      return res.text().then(function (text) {
        var data = null;
        if (text) {
          try {
            data = JSON.parse(text);
          } catch (e) {
            data = null;
          }
        }
        if (!res.ok) {
          var msg = data && data.error ? data.error : '請求失敗（狀態碼 ' + res.status + '）';
          throw new Error(msg);
        }
        if (data === null) {
          throw new Error('伺服器回應格式不正確');
        }
        return data;
      });
    });
  }

  function showError(err) {
    var text = err && err.message ? err.message : String(err);
    messageEl.textContent = '錯誤：' + text;
    messageEl.hidden = false;
  }

  function clearError() {
    messageEl.textContent = '';
    messageEl.hidden = true;
  }

  // ---- remaining-counter ----
  function loadStats() {
    return apiRequest('GET', 'stats').then(function (stats) {
      counterEl.textContent = '尚未完成：' + stats.remaining + ' / ' + stats.total;
    });
  }

  // ---- todo-list ----
  function renderTodos(items) {
    listEl.textContent = '';
    emptyEl.hidden = items.length > 0;
    items.forEach(function (todo) {
      var li = document.createElement('li');
      li.className = 'todo-item' + (todo.done ? ' done' : '');

      var checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.checked = !!todo.done;
      checkbox.setAttribute('aria-label', '標記完成：' + todo.title);
      checkbox.addEventListener('change', function () {
        toggleTodo(todo.id, checkbox.checked, checkbox);
      });

      var span = document.createElement('span');
      span.className = 'todo-title';
      span.textContent = todo.title;

      var del = document.createElement('button');
      del.type = 'button';
      del.className = 'delete-button';
      del.textContent = '刪除';
      del.addEventListener('click', function () {
        deleteTodo(todo.id);
      });

      li.appendChild(checkbox);
      li.appendChild(span);
      li.appendChild(del);
      listEl.appendChild(li);
    });
  }

  function loadTodos() {
    return apiRequest('GET', 'todos').then(function (data) {
      renderTodos(data.items || []);
    });
  }

  function refresh() {
    return Promise.all([loadTodos(), loadStats()]);
  }

  function toggleTodo(id, done, checkbox) {
    clearError();
    apiRequest('PATCH', 'todos/' + encodeURIComponent(id), { done: done })
      .then(refresh)
      .catch(function (err) {
        checkbox.checked = !done;
        showError(err);
      });
  }

  function deleteTodo(id) {
    clearError();
    apiRequest('DELETE', 'todos/' + encodeURIComponent(id))
      .then(refresh)
      .catch(showError);
  }

  // ---- add-form ----
  form.addEventListener('submit', function (event) {
    event.preventDefault();
    clearError();
    var title = input.value.trim();
    if (!title) {
      showError(new Error('標題不可為空'));
      input.focus();
      return;
    }
    addButton.disabled = true;
    apiRequest('POST', 'todos', { title: title })
      .then(function () {
        input.value = '';
        return refresh();
      })
      .catch(showError)
      .then(function () {
        addButton.disabled = false;
        input.focus();
      });
  });

  refresh().catch(showError);
})();

