* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: -apple-system, "Noto Sans TC", "PingFang TC", "Microsoft JhengHei", sans-serif;
  background: #f3f4f6;
  color: #1f2937;
}

.container {
  max-width: 520px;
  margin: 40px auto;
  padding: 24px;
  background: #ffffff;
  border-radius: 12px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
}

h1 {
  margin: 0 0 16px;
  font-size: 1.5rem;
}

#add-form {
  display: flex;
  gap: 8px;
}

#title-input {
  flex: 1;
  padding: 8px 10px;
  font-size: 1rem;
  border: 1px solid #d1d5db;
  border-radius: 6px;
}

button {
  padding: 8px 14px;
  font-size: 1rem;
  border: none;
  border-radius: 6px;
  background: #2563eb;
  color: #ffffff;
  cursor: pointer;
}

button:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.delete-button {
  background: #dc2626;
  padding: 4px 10px;
  font-size: 0.9rem;
}

.message {
  margin-top: 12px;
  padding: 8px 10px;
  background: #fee2e2;
  color: #991b1b;
  border-radius: 6px;
}

.counter {
  margin: 16px 0 8px;
  font-weight: bold;
}

.todo-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.todo-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 4px;
  border-bottom: 1px solid #e5e7eb;
}

.todo-title {
  flex: 1;
  word-break: break-word;
}

.todo-item.done .todo-title {
  text-decoration: line-through;
  opacity: 0.5;
}

.empty {
  color: #6b7280;
  text-align: center;
}
